# Corruption Detection Scanner demo: checksum + structure + truncation checks.
import hashlib,struct
def sha(b): return hashlib.sha256(b).hexdigest()
FILES={"good":{"declared":8,"stored_sha":sha(b"ABCDEFGH"),"data":b"ABCDEFGH"},
       "truncated":{"declared":8,"stored_sha":sha(b"ABCDEFGH"),"data":b"ABCD"},
       "bitrot":{"declared":8,"stored_sha":sha(b"ABCDEFGH"),"data":b"ABCXEFGH"}}
for name,f in FILES.items():
    problems=[]
    if len(f["data"])!=f["declared"]: problems.append("truncated")
    if sha(f["data"])!=f["stored_sha"]: problems.append("checksum-mismatch")
    print(name,"->",problems or ["clean"])

